  }
}

expected_completion:
if (event.pointerType !== "touch" && event.pointerType !== "mouse") return;
    event.preventDefault();

    if (pressed) {
      if (event.currentTarget?.setPointerCapture) {
        event.currentTarget.setPointerCapture(event.pointerId);
      }
      this.activeFirePointers.add(event.pointerId);
    } else {
      this.activeFirePointers.delete(event.pointerId);
    }

    const shouldFire = this.activeFirePointers.size > 0;
    if (shouldFire === this.isFiring) return;

    this.isFiring = shouldFire;
    this.weapon.setTriggerHeld(shouldFire);

