class TouchLookController {
  constructor(camera, sensitivity, pitchLimit) {
    this.camera = camera;
    this.sensitivity = sensitivity;
    this.pitchLimit = pitchLimit;
    this.lookPointerId = null;
    this.lastTouch = { x: 0, y: 0 };
  }

  handleLookMove(event) {
    if (event.pointerId !== this.lookPointerId) return;
    // TODO: Apply touch deltas to camera yaw and clamped pitch.
  }
}

expected_completion:
const deltaX = event.clientX - this.lastTouch.x;
    const deltaY = event.clientY - this.lastTouch.y;
    this.lastTouch.x = event.clientX;
    this.lastTouch.y = event.clientY;

    const yaw = this.camera.yaw + deltaX * this.sensitivity;
    const pitch = this.camera.pitch - deltaY * this.sensitivity;
    this.camera.yaw = yaw;
    this.camera.pitch = Math.max(-this.pitchLimit, Math.min(this.pitchLimit, pitch));

