  constructor(player, joystickRadius) {
    this.player = player;
    this.joystickRadius = joystickRadius;
    this.movePointerId = null;
    this.moveOrigin = { x: 0, y: 0 };
  }

  handleMoveTouch(event) {
    if (event.pointerId !== this.movePointerId) return;
    // TODO: Convert the touch displacement into normalized movement input.
  }
}

